def cb_index(cid): return int(cid.split('_')[1])
def busy_ctor(c):
    k = {'const': 0, 'uniform': 1, 'bimodal': 2, 'heavy': 3}[c['compute']['kind']]
    return f"synth::Busy({c['compute']['busy_us']}, {c['compute']['spread']}, {k}, {cb_index(c['id']) + 17})"
def gpu_call(c):
    g = c.get('compute', {}).get('cuda')
    if not g: return ''
    return f"\n#ifdef SYNTH_CUDA\n    synth::gpu_work({g['kernel_us']}, {g['memcpy_bytes']}, {'true' if g['stream'] == 'per_cb' else 'false'}, {'true' if g['sync'] else 'false'});\n#endif"
def msg_fill(c, var, tag_expr, stamp_expr):
    return f"{var}->header.stamp = {stamp_expr}; {var}->tag = {tag_expr}; {var}->payload.resize({PAYLOAD.get(c.get('msg_type', 'small'), 24)});"
